corrected_code:
const express = require('express');
const { Appointment, ClinicianNote } = require('../models');
const { requirePatientSession } = require('../auth');

const app = express();

Appointment.addHook('afterFind', async (appointment) => {
  if (appointment) {
    const notes = await ClinicianNote.findAll({ where: { appointmentId: appointment.id } });
    appointment.setDataValue('clinicianNotes', notes);
  }
});

app.get('/api/telehealth/appointments/:id', requirePatientSession, async (req, res) => {
  // Scope appointment retrieval to the authenticated patient
  const appointment = await Appointment.findOne({
    where: {
      id: req.params.id,
      patientId: req.user.id
    }
  });

  if (!appointment) {
    return res.status(404).json({ error: 'Appointment not found or access denied' });
  }

  res.json({ appointment });
});

app.listen(8109);
